use crate::storage::Database;use rusqlite::params;use serde_json::{json,Value};
use windows_service::{service::ServiceAccess,service_manager::{ServiceManager,ServiceManagerAccess}};
use windows_sys::Win32::System::Services::{ChangeServiceConfigW,ChangeServiceConfig2W,SERVICE_NO_CHANGE,SERVICE_CONFIG_DELAYED_AUTO_START_INFO,SERVICE_DELAYED_AUTO_START_INFO};
pub fn permitted(name:&str)->bool{["Fax","RetailDemo"].iter().any(|n|n.eq_ignore_ascii_case(name))}
fn trusted_image(value:&Value)->Result<(),String>{use std::os::windows::ffi::OsStringExt;let name=value["name"].as_str().unwrap_or("");let image=value["executable"].as_str().unwrap_or("");if name.eq_ignore_ascii_case("RetailDemo")&&std::env::var("GITHUB_ACTIONS").as_deref()==Ok("true")&&std::env::var("RUNNER_OS").as_deref()==Ok("Windows"){let expected=format!("\"{}\" --service-fixture-never-run",std::env::current_exe().map_err(|e|e.to_string())?.to_string_lossy());if image==expected{return Ok(())}}let mut buffer=vec![0u16;32768];let length=unsafe{windows_sys::Win32::System::SystemInformation::GetWindowsDirectoryW(buffer.as_mut_ptr(),buffer.len() as u32)};if length==0||length as usize>=buffer.len(){return Err("Não foi possível verificar a pasta real do Windows".into())}let system=std::path::PathBuf::from(std::ffi::OsString::from_wide(&buffer[..length as usize]));let expected=system.join("System32/fxssvc.exe");if !name.eq_ignore_ascii_case("Fax")||!image.trim().trim_matches('"').eq_ignore_ascii_case(&expected.to_string_lossy()){return Err("Não suportado: o executável não corresponde ao serviço Windows reconhecido".into())}if !expected.is_file(){return Err("O executável reconhecido não está instalado".into())}Ok(())}
pub fn eligible(value:&Value)->Result<(),String>{let name=value["name"].as_str().unwrap_or("");if !permitted(name){return Err("Não suportado para escrita: apenas Fax e RetailDemo são permitidos nesta versão".into())}if value["service_type"].as_u64()!=Some(0x10){return Err("Serviços partilhados, drivers e outros tipos estão protegidos".into())}if value["state"]!="Stopped"{return Err("O serviço está em utilização; não é parado automaticamente".into())}if value["start_code"].as_u64()!=Some(2){return Err("O serviço já não está em arranque automático; manter a configuração atual".into())}if value["trigger_count"].as_u64()!=Some(0){return Err("Triggers presentes ou não verificáveis; manter configuração".into())}if !value["dependency_error"].is_null()||value["dependents"].as_array().is_none_or(|v|!v.is_empty()){return Err("Dependentes presentes ou não verificáveis".into())}if !value["delayed"].is_boolean(){return Err("Arranque diferido não verificável".into())}Ok(())}
pub fn review(name:&str)->Result<Value,String>{let mut value=crate::service_manager::inspect(name)?;let decision=eligible(&value).and_then(|_|trusted_image(&value));value["can_set_manual"]=json!(decision.is_ok());value["change_reason"]=json!(decision.err().unwrap_or_else(||"Pode propor início manual; confirme que não utiliza esta funcionalidade. Não são prometidos ganhos.".into()));Ok(value)}
pub fn helper(name:&str,expected:u32,target:u32,delayed:bool)->Result<(),String>{
 if !permitted(name)||!matches!((expected,target),(2,3)|(3,2)){return Err("Operação de serviço fora da allowlist".into())}
 let before=crate::service_manager::inspect(name)?;trusted_image(&before)?;if before["start_code"].as_u64()!=Some(expected as u64){return Err("A configuração mudou desde a confirmação".into())}if target==3{eligible(&before)?;if before["delayed"]!=delayed{return Err("O arranque diferido mudou desde a confirmação".into())}}else if before["service_type"].as_u64()!=Some(0x10){return Err("Tipo de serviço protegido".into())}
 let manager=ServiceManager::local_computer(None::<&str>,ServiceManagerAccess::CONNECT).map_err(|e|e.to_string())?;let service=manager.open_service(name,ServiceAccess::CHANGE_CONFIG|ServiceAccess::QUERY_CONFIG).map_err(|e|e.to_string())?;
 let ok=unsafe{ChangeServiceConfigW(service.raw_handle() as _,SERVICE_NO_CHANGE,target,SERVICE_NO_CHANGE,std::ptr::null(),std::ptr::null(),std::ptr::null_mut(),std::ptr::null(),std::ptr::null(),std::ptr::null(),std::ptr::null())};if ok==0{return Err(std::io::Error::last_os_error().to_string())}
 if target==2{let info=SERVICE_DELAYED_AUTO_START_INFO{fDelayedAutostart:i32::from(delayed)};let ok=unsafe{ChangeServiceConfig2W(service.raw_handle() as _,SERVICE_CONFIG_DELAYED_AUTO_START_INFO,&info as *const _ as _)};if ok==0{let error=std::io::Error::last_os_error().to_string();unsafe{ChangeServiceConfigW(service.raw_handle() as _,SERVICE_NO_CHANGE,expected,SERVICE_NO_CHANGE,std::ptr::null(),std::ptr::null(),std::ptr::null_mut(),std::ptr::null(),std::ptr::null(),std::ptr::null(),std::ptr::null());}return Err(error)}}
 let after=crate::service_manager::inspect(name)?;if after["start_code"].as_u64()!=Some(target as u64)||(target==2&&after["delayed"]!=delayed){return Err("A alteração não foi verificada".into())}Ok(())
}
fn elevate(name:&str,expected:u32,target:u32,delayed:bool)->Result<(),String>{
 use windows_sys::Win32::{UI::Shell::{ShellExecuteExW,SHELLEXECUTEINFOW,SEE_MASK_NOCLOSEPROCESS},System::Threading::{WaitForSingleObject,GetExitCodeProcess,INFINITE},Foundation::CloseHandle};use std::os::windows::ffi::OsStrExt;
 if !permitted(name)||!matches!((expected,target),(2,3)|(3,2)){return Err("Operação não permitida".into())}
 let exe=std::env::current_exe().map_err(|e|e.to_string())?;let file:Vec<u16>=exe.as_os_str().encode_wide().chain(Some(0)).collect();let verb:Vec<u16>="runas\0".encode_utf16().collect();let args=format!("--service-helper {name} {expected} {target} {}",u8::from(delayed));let args:Vec<u16>=args.encode_utf16().chain(Some(0)).collect();
 let mut info:SHELLEXECUTEINFOW=unsafe{std::mem::zeroed()};info.cbSize=std::mem::size_of::<SHELLEXECUTEINFOW>() as u32;info.fMask=SEE_MASK_NOCLOSEPROCESS;info.lpVerb=verb.as_ptr();info.lpFile=file.as_ptr();info.lpParameters=args.as_ptr();info.nShow=0;
 if unsafe{ShellExecuteExW(&mut info)}==0{return Err(format!("Pedido UAC não concluído: {}",std::io::Error::last_os_error()))}if info.hProcess.is_null(){return Err("O Windows não devolveu o handle do helper".into())}
 unsafe{WaitForSingleObject(info.hProcess,INFINITE);};let mut code=1;let ok=unsafe{GetExitCodeProcess(info.hProcess,&mut code)};unsafe{CloseHandle(info.hProcess);};if ok==0||code!=0{return Err(format!("O helper recusou ou não conseguiu verificar a operação (código {code}). Consulte o estado atual antes de repetir."))}Ok(())
}
pub fn apply(db:&Database,name:&str,expected:&Value)->Result<Value,String>{let old=review(name)?;eligible(&old)?;trusted_image(&old)?;if old["start_code"]!=expected["start_code"]||old["delayed"]!=expected["delayed"]||old["executable"]!=expected["executable"]{return Err("O serviço mudou desde a pré-visualização".into())}let conn=db.0.lock().map_err(|e|e.to_string())?;conn.execute("INSERT INTO changes(optimization_id,previous_value,new_value,status,category) VALUES('services.manual',?1,?2,'pending','Serviços')",params![old.to_string(),json!({"name":name,"start_code":3}).to_string()]).map_err(|e|e.to_string())?;let id=conn.last_insert_rowid();drop(conn);let result=elevate(name,2,3,old["delayed"].as_bool().ok_or("Arranque diferido ausente")?).and_then(|_|{let v=review(name)?;if v["start_code"]!=3{return Err("Verificação falhou".into())}Ok(())});db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status=?1,error=?2 WHERE id=?3",params![if result.is_ok(){"applied"}else{"failed"},result.as_ref().err(),id]).map_err(|e|e.to_string())?;db.log("service.manual",&json!({"id":id,"name":name,"success":result.is_ok()}).to_string())?;result?;Ok(json!({"id":id,"verified":true}))}
pub fn restore(db:&Database,id:i64)->Result<Value,String>{let conn=db.0.lock().map_err(|e|e.to_string())?;let(old,status):(String,String)=conn.query_row("SELECT previous_value,status FROM changes WHERE id=?1 AND optimization_id='services.manual'",[id],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|e|e.to_string())?;drop(conn);if status=="restored"{return Ok(json!({"status":"restored"}))}let old:Value=serde_json::from_str(&old).map_err(|e|e.to_string())?;let name=old["name"].as_str().ok_or("Backup inválido")?;if !permitted(name)||old["start_code"]!=2{return Err("Backup fora da allowlist".into())}let now=review(name)?;if now["executable"]!=old["executable"]{return Err("O executável do serviço mudou; restauro bloqueado".into())}let delayed=old["delayed"].as_bool().ok_or("Backup sem arranque diferido")?;if now["start_code"]==3{elevate(name,3,2,delayed)?;}else if now["start_code"]!=2||now["delayed"]!=delayed{return Err("Configuração alterada externamente; nada foi sobrescrito".into())}db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status='restored',error=NULL WHERE id=?1",[id]).map_err(|e|e.to_string())?;db.log("service.restore",&id.to_string())?;Ok(json!({"status":"restored","verified":true}))}
#[cfg(test)]mod tests{use super::*;#[test]fn security_and_shared_services_are_never_eligible(){for name in ["WinDefend","wuauserv","Spooler","MapsBroker","BthServ","FaxExtra","RpcSs"]{assert!(!permitted(name));}let mut value=json!({"name":"Fax","state":"Stopped","start_code":2,"service_type":16,"trigger_count":0,"dependency_error":null,"dependents":[],"delayed":false});assert!(eligible(&value).is_ok());for(field,bad)in [("service_type",json!(32)),("trigger_count",json!(1)),("state",json!("Running")),("dependents",json!(["Dependent"]))]{let mut changed=value.clone();changed[field]=bad;assert!(eligible(&changed).is_err());}value["name"]=json!("WinDefend");assert!(eligible(&value).is_err());}}
